use super::words;

pub(super) const GENERATOR_WORDS: &words::Point = &GENERATOR_WORDS_BY_DIGIT[9 * SIDE + 8];
const SIDE: usize = 17;

pub(super) fn point(first: i8, second: i8) -> &'static words::Point {
    debug_assert!((-8..=8).contains(&first) && (-8..=8).contains(&second));
    &GENERATOR_WORDS_BY_DIGIT
        [usize::from((first + 8) as u8) * SIDE + usize::from((second + 8) as u8)]
}

