#[cfg(test)]
mod tests {
    use super::*;
    use crate::ProjectivePoint;

    fn signed_multiples(base: ProjectivePoint) -> [ProjectivePoint; SIDE] {
        let mut points = [ProjectivePoint::IDENTITY; SIDE];
        for i in 1..=8 {
            let value = points[8 + i - 1] + base;
            points[8 + i] = value;
            points[8 - i] = -value;
        }
        points
    }

    #[test]
    fn fixed_generator_matches_all_signed_pairs() {
        let first = signed_multiples(ProjectivePoint::GENERATOR);
        let second = signed_multiples(ProjectivePoint::GENERATOR.endomorphism());
        for (a, left) in first.into_iter().enumerate() {
            for (b, right) in second.into_iter().enumerate() {
                let actual = words::to_point(point(a as i8 - 8, b as i8 - 8));
                assert_eq!(actual, left + right);
            }
        }
    }
}
